function incidentOpen(p){return !!p&&p.status!=='Réparée'&&p.status!=='Résolu'}function incidentCreatedOrder(p,index){let d=Date.parse(p?.createdAt||p?.createdOn||'');if(Number.isFinite(d))return d;let m=String(p?.id||'').match(/(?:^|\D)(\d{13})(?:\D|$)/);return m?Number(m[1]):index}function incidentSeverity(p){return p?.gravite||p?.severity||'immobilisant'}function hasOpenImmobilizing(v){return (v.pannes||[]).some(p=>incidentOpen(p)&&incidentSeverity(p)==='immobilisant')}function syncVehicleCondition(v){if(v.status==='actif'&&hasOpenImmobilizing(v))v.condition='HS';else if(v.status==='actif')v.condition='ROULANT'}
