function login(){if($('#login-pass').value!=='flotte2026'){toast('Code incorrect. Utilisez flotte2026 pour la démo.');return}role=$('#login-role').value;sessionStorage.setItem(SESSION,role);pole='home';page='home';showApp()}
/* UTILISATEURS - début */function showApp(){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#who').textContent=roleName();$('#top-role').textContent=roleName();$('.role-box .avatar').textContent=roleName()[0];$('.user-chip .avatar').textContent=roleName()[0];document.querySelectorAll('[data-admin-only]').forEach(el=>{el.hidden=!canAccessAdmin()});normalizeNavigationState();updatePoleNavigation();updateCrumb(page);render()}/* UTILISATEURS - fin */
/* UTILISATEURS - début */let gpLast=null;
function gpScroll(){return{y:window.scrollY||0,m:(document.querySelector('.main')||{}).scrollTop||0,c:($('#content')||{}).scrollTop||0}}
function gpSnap(){let f={};try{f=JSON.parse(JSON.stringify(filters))}catch(e){}return{page,pole,selected,selectedDepot,selectedSalarie,alertFilter,alertTypeFilter,filters:f,paieMonth,recapDate,recapDepot,recapView,recapTab,dashSplit}}
function gpLabel(s){const m={home:'Accueil',dashboard:'Vue d’ensemble',vehicles:'Véhicules',alerts:'Alertes',archive:'Archives',depots:'Dépôts',rentals:'Locations',users:'Utilisateurs','paie-recap':'Récap paie','paie-overview':'Vue d’ensemble','paie-employees':'Salariés','paie-variables':'Éléments variables','paie-depots':'Dépôts','paie-fines':'Amendes','admin-depots':'Dépôts','direction-routes':'Récap Routes','direction-prefac':'Suivi Préfac'};if(s.page==='detail')return (db.rentals||[]).some(r=>r.id===s.selected)||(db.rentalsArchive||[]).some(r=>r.id===s.selected)?'Fiche location':'Fiche '+(s.selected||'véhicule');if(s.page==='paie-employee'){const x=paieSalaries().find(y=>y.id===s.selectedSalarie);return x?('Fiche '+(x.firstName||'')+' '+(x.lastName||'')).trim():'Fiche salarié'}if(s.page==='depotDetail'||s.page==='paie-depot-detail')return s.selectedDepot==='__unassigned__'?'À affecter':'Dépôt '+(s.selectedDepot||'');return m[s.page]||'Retour'}
function gpValid(s){if(s.page==='detail')return db.vehicles.some(v=>v.plate===s.selected)||(db.rentals||[]).some(r=>r.id===s.selected)||(db.rentalsArchive||[]).some(r=>r.id===s.selected);if(s.page==='paie-employee')return paieSalaries().some(y=>y.id===s.selectedSalarie);return true}
function gpBackInfo(){const st=history.state;return st&&st.gp&&st.link&&st.from?{from:st.from}:null}
function gpPush(prev,sc,menu){if(!prev)return;try{const cur=gpSnap(),same=prev.page===cur.page&&prev.pole===cur.pole&&prev.selected===cur.selected&&prev.selectedDepot===cur.selectedDepot&&prev.selectedSalarie===cur.selectedSalarie;if(same)return;if(history.state&&history.state.gp)history.replaceState({...history.state,snap:prev,scroll:sc},'');else history.replaceState({gp:1,snap:prev,link:false,from:'',scroll:sc,trail:[gpLabel(prev)]},'');history.pushState({gp:1,snap:cur,link:!menu,from:menu?'':gpLabel(prev),trail:menu?[gpLabel(cur)]:((history.state&&history.state.trail)||[gpLabel(prev)]).concat(gpLabel(cur))},'')}catch(e){}}
function gpApply(st){const s=st.snap;if(!s)return;const ok=gpValid(s);page=ok?s.page:(s.page==='detail'?'vehicles':s.page==='paie-employee'?'paie-employees':s.page);pole=s.pole;selected=s.selected;selectedDepot=s.selectedDepot;selectedSalarie=s.selectedSalarie;alertFilter=s.alertFilter;alertTypeFilter=s.alertTypeFilter;filters={...filters,...s.filters};paieMonth=s.paieMonth;recapDate=s.recapDate;recapDepot=s.recapDepot;recapView=s.recapView;recapTab=s.recapTab;dashSplit=s.dashSplit||dashSplit;rememberPole();updatePoleNavigation();updateCrumb(page);render();const sc=st.scroll;if(sc)requestAnimationFrame(()=>{window.scrollTo(0,sc.y||0);const m=document.querySelector('.main');if(m)m.scrollTop=sc.m||0;const c=$('#content');if(c)c.scrollTop=sc.c||0})}
function gpBack(fbPage,fbLabel,id){const b=gpBackInfo();return `<button type="button" class="link-button gp-back"${id?` id="${id}"`:''} data-gp-back="${fbPage||''}"><i data-lucide="arrow-left" aria-hidden="true"></i> ${esc(b?b.from:(fbLabel||'Retour'))}</button>`}
function gpInject(target){if(!gpBackInfo()||target.querySelector('.gp-back'))return;const host=target.querySelector('.page-head>div')||target.firstElementChild;if(host)host.insertAdjacentHTML('afterbegin',gpBack('',''))}
function gpTopBack(){const bar=document.querySelector('.topbar'),app=$('#app');if(!bar)return;let b=$('#gp-top-back');if(!b){b=document.createElement('button');b.type='button';b.id='gp-top-back';b.className='icon-btn gp-top-back';b.setAttribute('data-gp-back','');bar.insertBefore(b,bar.firstChild)}const i=gpBackInfo();b.innerHTML=i?`<i data-lucide="arrow-left" aria-hidden="true"></i><span>${esc(i.from)}</span>`:'';b.setAttribute('aria-label',i?'Retour : '+i.from:'Retour');if(app)app.classList.toggle('gp-has-back',!!i);if(i)refreshLucideIcons()}
function gpCrumb(){const bc=document.querySelector('.breadcrumb'),cur=$('#crumb');if(!bc||!cur)return;bc.querySelectorAll('.gp-trail').forEach(x=>x.remove());const tr=(history.state&&history.state.gp&&history.state.trail)||[];bc.classList.toggle('has-trail',tr.length>1);if(tr.length<2)return;const from=Math.max(0,tr.length-5);let h=from>0?'<span class="gp-trail gp-ellipsis">…</span><b class="gp-trail">›</b>':'';for(let i=from;i<tr.length-1;i++)h+=`<button type="button" class="gp-trail gp-step" data-gp-crumb="${i}">${esc(tr[i])}</button><b class="gp-trail">›</b>`;cur.insertAdjacentHTML('beforebegin',h)}
