if(!window.__gpNavBound){window.__gpNavBound=true;try{history.replaceState({gp:1,snap:null,link:false,from:''},'')}catch(e){}window.gpNavMenu=false;document.addEventListener('click',e=>{window.gpNavMenu=!!e.target.closest('#side-nav,#bottom-nav,[data-pole],.home-btn,.mobile-logo,#mobile-pole-menu');setTimeout(()=>{window.gpNavMenu=false},0);if(e.target.closest('.mobile-logo')&&!$('#app').classList.contains('hidden'))nav('home');const b=e.target.closest('[data-gp-back]');if(b){e.preventDefault();gpGoBack(b.dataset.gpBack)}const cr=e.target.closest('[data-gp-crumb]');if(cr){e.preventDefault();const tr=(history.state&&history.state.trail)||[],n=tr.length-1-Number(cr.dataset.gpCrumb);if(n>0)history.go(-n)}},true);window.addEventListener('popstate',e=>{const st=e.state;if(st&&st.gp&&st.snap&&!$('#app').classList.contains('hidden'))gpApply(st)})}
function nav(p){const gpPrev=gpLast,gpSc=gpScroll();if((p==='admin-depots'||p==='users'||administrationPage(p))&&!canAccessAdmin()){toast('Accès Administration réservé aux rôles Responsable et Administrateur.');normalizeNavigationState();updatePoleNavigation();return}/* UTILISATEURS - fin */if(directionPage(p)&&!canAccessAdmin()){toast('Accès Direction réservé aux rôles Responsable et Administrateur.');normalizeNavigationState();updatePoleNavigation();return}/* PAIE - début */if(paiePage(p)&&!canAccessPaiePage(p)){toast(p==='paie-recap'?'Accès Paie réservé aux rôles autorisés.':'Chef d’équipe : seul le récapitulatif du jour est accessible dans Paie.');return}if(paiePage(p))pole='paie';else if(directionPage(p))pole='direction';else if(administrationPage(p)||p==='users')pole='administration';else if(['dashboard','vehicles','rentals','depots','alerts','archive','detail','depotDetail'].includes(p))pole='flotte';else if(p==='home')pole='home';page=p;rememberPole();updatePoleNavigation();updateCrumb(p);gpPush(gpPrev,gpSc,!!window.gpNavMenu);render()}
