function activeVehicles(){return db.vehicles.filter(v=>v.status==='actif'&&v.ownership!=='LOCATION')}
function escapeAttr(s){return esc(s).replace(/`/g,'&#96;')}
/* UTILISATEURS - début */function render(){const hadAdminRoute=administrationPage()||page==='users';normalizeNavigationState();if(hadAdminRoute&&!canAccessAdmin())toast('Accès Administration réservé aux rôles Responsable et Administrateur.');updatePoleNavigation();const alertNode=$('#nav-alert-count');if(alertNode)alertNode.textContent=allAlerts().length;const target=$('#content');if(page==='direction-prefac'&&canAccessAdmin())target.innerHTML=prefacPage();else if(page==='direction-routes'&&canAccessAdmin())target.innerHTML=directionRoutesPage();else if(page==='admin-depots'&&canAccessAdmin())target.innerHTML=adminDepotsPage();else if(page==='paie-recap'&&canAccessPaiePage())target.innerHTML=paieRecapPage();else if(page==='paie-fines'&&canAccessPaie())target.innerHTML=paieFinesPage();else if(page==='paie-depots'&&canAccessPaie())target.innerHTML=paieDepotsPage();else if(page==='paie-depot-detail'&&canAccessPaie())target.innerHTML=paieDepotDetailPage();else if(page==='users'&&canAccessAdmin())target.innerHTML=usersPage();else if(page==='paie-overview'&&canAccessPaie())target.innerHTML=paieOverview();else if(page==='paie-employees'&&canAccessPaie())target.innerHTML=paieEmployeesPage();else if(page==='paie-variables'&&canAccessPaie())target.innerHTML=paieVariablesPage();else if(page==='paie-employee'&&canAccessPaie())target.innerHTML=paieEmployeePage();else if(page==='home')target.innerHTML=homePage();else if(page==='dashboard')target.innerHTML=dashboard();else if(page==='vehicles')target.innerHTML=vehiclesPage();else if(page==='rentals')target.innerHTML=rentalsPage();else if(page==='alerts')target.innerHTML=alertsPage();else if(page==='archive')target.innerHTML=archivePage();else if(page==='depots')target.innerHTML=depotsPage();else if(page==='depotDetail')target.innerHTML=depotDetailPage();else if(page==='detail')target.innerHTML=(db.rentals.some(r=>r.id===selected)||(db.rentalsArchive||[]).some(r=>r.id===selected))?rentalDetailPage():detailPage();gpInject(target);bindPage();refreshLucideIcons();gpLast=gpSnap();gpTopBack();gpCrumb()}/* UTILISATEURS - fin */
