const PAIE_MONTHS_SHORT=['janv.','févr.','mars','avr.','mai','juin','juil.','août','sept.','oct.','nov.','déc.'];
function paieMonthNav(id,value){const now=new Date().toISOString().slice(0,7);return `<div class="gp-mp"><button type="button" class="gp-mp-b" data-mp-step="-1" aria-label="Mois précédent"><i data-lucide="chevron-left" aria-hidden="true"></i></button><button type="button" class="gp-mp-lbl" data-mp-open aria-haspopup="true">${esc(paieMonthLabel(value))}</button><button type="button" class="gp-mp-b" data-mp-step="1" aria-label="Mois suivant"><i data-lucide="chevron-right" aria-hidden="true"></i></button>${value===now?'':'<button type="button" class="gp-mp-now" data-mp-now>Ce mois</button>'}<input id="${id}" type="month" value="${escapeAttr(value)}" hidden></div>`}
