function paieDebtTipHtml(id){const i=paieIncident(id);if(!i)return '';const pays=paieEntries().filter(e=>e.incidentId===id).sort((a,b)=>(a.month||'').localeCompare(b.month||'')),taken=paieIncidentTaken(id),rest=Math.max(0,paieIncidentRest(i));
 return `<b class="gp-tip-t">${esc(i.nature)} · prélevé ${paieMoney(taken)} sur ${paieMoney(i.cost)}</b>${pays.length?`<div class="gp-tip-g">${pays.map(e=>`<span>${esc(paieMonthShort(e.month))}${e.status==='validated'?'':' (brouillon)'}</span><b>${paieMoney(e.amount)}</b>`).join('')}</div>`:'<div class="gp-tip-n">Aucun prélèvement pour le moment</div>'}${i.closed?`<div class="gp-tip-f">${i.closed.outcome==='recover'?'À recouvrer':'Abandonnée'} · reste ${paieMoney(rest)}</div>`:rest>0?`<div class="gp-tip-f">Reste à facturer <b>${paieMoney(rest)}</b></div>`:'<div class="gp-tip-f">Dette soldée ✓</div>'}`}

const PAIE_EXIT_PROCEDURES=[['Rupture du CDI · à l’initiative de l’employeur',['Licenciement pour faute simple','Licenciement pour faute grave','Licenciement pour faute lourde','Licenciement pour insuffisance professionnelle','Licenciement pour inaptitude','Licenciement pour motif économique']],['Rupture du CDI · autres',['Démission','Rupture conventionnelle','Abandon de poste (mise en demeure)','Départ ou mise à la retraite','Prise d’acte / résiliation judiciaire']],['Période d’essai · CDD · intérim · autres',['Rupture de la période d’essai','Fin de CDD (terme du contrat)','Rupture anticipée de CDD','Fin de mission d’intérim','Décès','Autre']]];
