 const ex=sal.exit&&sal.exit.state!=='dropped'?sal.exit:null,editing=!!ex,stt=paieInProcedure(sal)?'En procédure de sortie':sal.status==='active'?'actuellement Actif':sal.status==='sorti'?'Sorti':'Inactif';
 const body=`<form id="paie-exit-form" class="form-grid"><label>Procédure<select name="procedure" required><option value="">Choisir…</option>${paieExitOptions(ex?.procedure||'')}</select></label><label>Date de sortie <span class="salary-optional">(prévue ou réelle)</span><input name="date" type="date" value="${escapeAttr(ex?.effectiveDate||ex?.plannedDate||'')}"></label><label>Dernier jour travaillé <span class="salary-optional">(par défaut : la veille)</span><input name="lastWorked" type="date" value="${escapeAttr(ex?.lastWorked||'')}"></label><label class="paie-wide">Motif de la sortie<input name="motif" required maxlength="300" placeholder="Ex. absences répétées non justifiées en septembre…" value="${escapeAttr(ex?.motif||'')}"></label><label class="paie-wide">Commentaire (facultatif)<textarea name="comment" rows="2">${esc(ex?.comment||'')}</textarea></label></form>${paieDebtWarn(sal.id)}${editing?'':`<div class="gp-info b"><i data-lucide="info" aria-hidden="true"></i><span><b>Deux possibilités.</b> « Ouvrir le dossier » démarre la procédure : le salarié passe <b>En procédure de sortie</b> (il n’apparaît plus dans la saisie après son dernier jour travaillé) et vous ajoutez les courriers au fil de l’eau. « Confirmer la sortie » le passe tout de suite en <b>Sorti</b>.</span></div>`}`;
