 openModal(editing?'Modifier la sortie':'Sortir le salarié',body,foot,`<span class="modal-plate">${esc(sal.name)}</span>${esc(sal.depot||'À affecter')} · ${stt}`);
 const read=()=>{const f=$('#paie-exit-form');if(!f.reportValidity())return null;const o=Object.fromEntries(new FormData(f).entries());return {procedure:o.procedure,date:o.date||'',lastWorked:o.lastWorked||'',motif:String(o.motif||'').trim(),comment:String(o.comment||'').trim()}};
 const o1=$('#paie-exit-open');if(o1)o1.onclick=()=>{const o=read();if(!o)return;sal.exit={procedure:o.procedure,motif:o.motif,comment:o.comment,plannedDate:o.date,lastWorked:o.lastWorked,state:'open',openedAt:new Date().toISOString()};save();closeModal();render();toast('Dossier de sortie ouvert : le salarié passe « En procédure de sortie ». Ajoutez les pièces au fil de l’eau.')};
 const o2=$('#paie-exit-go');if(o2)o2.onclick=()=>{const o=read();if(!o)return;if(!o.date)return toast('Indiquez la date de sortie.');paieExitFinish(sal,{procedure:o.procedure,motif:o.motif,comment:o.comment},o.date,o.lastWorked)};
