 const f=$('#paie-recv-form'),renderEx=()=>{$('#recv-existing').innerHTML=keep.filter(d=>!removed.has(d.id)).map(d=>`<span class="ds-chipx">${esc(d.name)}<button type="button" data-recv-rm="${escapeAttr(d.id)}" aria-label="Retirer ${escapeAttr(d.name)}">×</button></span>`).join('');document.querySelectorAll('[data-recv-rm]').forEach(b=>b.onclick=()=>{removed.add(b.dataset.recvRm);renderEx()})};renderEx();
