function salaryStatusKey(x){return x.status==='sorti'?'sorti':paieInProcedure(x)?'procedure':x.status==='active'?'active':'inactif'}
function salaryNorm(t){return String(t||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase()}
