function salarySortValue(x,key){switch(key){case'name':return String(x.name||'');case'activity':return (x.activity||[]).join(' ');case'depot':return (x.depot||'')+'|'+(x.activity||[]).join(' ');case'docs':return salaryDocsCount(x);case'follow':return salaryFollow(x).sort;case'status':return {active:0,procedure:1,inactif:2,sorti:3}[salaryStatusKey(x)];case'rate':{const r=salaryRateAt(x);return r?Number(r.weeklyRate):null}case'history':return paieEntries().filter(e=>e.salaryId===x.id).length;default:return ''}}
