 const kindOk=e=>F.kind==='all'||(F.kind==='gain'&&!isRet(e))||(F.kind==='retenue'&&isRet(e));
 const scope=ents.filter(e=>okSal(sal(e.salaryId))||(!sal(e.salaryId)&&!F.depot&&!F.q)),shown=scope.filter(kindOk);
 const live=paieIncidents().filter(i=>!i.closed&&i.month<=mth&&paieIncidentRest(i)>0&&okSal(sal(i.salaryId))),gone=i=>sal(i.salaryId)?.status==='sorti',allDebts=live.filter(i=>!gone(i)),debts=F.kind==='gain'?[]:allDebts,partis=F.kind==='gain'?[]:live.filter(gone);
 const gains=scope.filter(e=>e.status==='validated'&&!isRet(e)).reduce((a,e)=>a+Number(e.amount||0),0),rets=scope.filter(e=>e.status==='validated'&&isRet(e)).reduce((a,e)=>a+Number(e.amount||0),0),drafts=scope.filter(e=>e.status!=='validated').length;
 const restTotal=allDebts.reduce((a,i)=>a+paieIncidentRest(i),0),net=gains-rets,ic=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
 const btn=(cls,attr,id,icon,label)=>`<button type="button" class="vr-ib ${cls}" ${attr}="${id}" title="${label}" aria-label="${label}">${ic(icon)}</button>`;
 const row=e=>{const t=paieType(e.type),ret=t[2]==='retenue',inc=e.type==='incident'?paieIncident(e.incidentId):null,ok=e.status==='validated',id=escapeAttr(e.id);
  let comment=inc?[inc.nature,e.comment].filter(Boolean).map(esc).join(' · '):esc(e.comment||'—');
  if(inc&&paieIncidentSolded(inc)){const l=paieIncidentPays(inc).slice(-1)[0];if(l&&l.id===e.id)comment+=' · <b class="vr-solded">Dette soldée ✓</b>'}
  return `<div class="vr-row"><span class="vr-t"><i class="${ret?'ret':'gain'}"></i>${esc(t[1])}</span><span class="vr-c">${comment}</span><span class="vr-m ${ret?'r':'g'}">${ret?'−':'+'} ${money(e.amount)}</span><span class="vr-s">${pill(ok?'Appliqué':'Brouillon',ok?'good':'warn')}</span><span class="vr-act">${ok?'':btn('ok','data-validate-variable',id,'check','Valider')}${btn('','data-edit-variable',id,'pencil','Modifier')}${btn('no','data-delete-variable',id,'trash-2','Supprimer')}</span></div>`};
 const debtRow=i=>{const taken=paieIncidentTaken(i.id),rest=paieIncidentRest(i),pct=i.cost>0?Math.min(100,Math.round(taken/i.cost*100)):0,id=escapeAttr(i.id);
  return `<div class="vr-row inc vr-carry"><span class="vr-t"><i class="ret"></i>Dette</span><span class="vr-c">${esc(i.nature)} · ${esc(paieIncidentWhen(i))}</span><span class="vr-m">${money(i.cost)}</span><span class="vr-s">${pill('À prélever','warn')}</span><span class="vr-act"><button type="button" class="btn primary small" data-incident-bill="${id}">Prélever</button>${btn('','data-edit-incident',id,'pencil','Modifier la dette')}${btn('no','data-delete-incident',id,'trash-2','Supprimer la dette')}</span><div class="vr-sub"><span>Montant total <b>${money(i.cost)}</b></span><span>Prélevé <b>${money(taken)}</b></span><span class="vr-bar2" data-debt-tip="${id}" tabindex="0" role="img" aria-label="Détail des prélèvements"><i style="width:${pct}%"></i></span><span class="todo">Reste à facturer ${money(rest)}</span></div></div>`};
