/* RECAP - début */
const FINE_STATUSES=['À traiter','Désigné','Retenue paie','Payée par entreprise','Contestée'];
function migrateFlexPointages(pointages){(pointages||[]).forEach(x=>{if(x?.status==='flex'){x.amount=0;x.prime=0;x.rateApplied=null}});return pointages}
function normalizePlate(value){const raw=String(value||'').toUpperCase().trim().replace(/[^A-Z0-9]/g,'');return /^[A-Z]{2}\d{3}[A-Z]{2}$/.test(raw)?`${raw.slice(0,2)}-${raw.slice(2,5)}-${raw.slice(5)}`:String(value||'').toUpperCase().trim().replace(/\s+/g,' ')}
function plateKey(value){return normalizePlate(value).replace(/[^A-Z0-9]/g,'')}
function driversForFine(plate,date){const key=plateKey(plate);if(!key||!date)return [];const ids=new Set(paiePointages().filter(x=>x.date===date&&recapRecordPlates(x).some(p=>plateKey(p)===key)).map(x=>x.salaryId));return paieSalaries().filter(x=>ids.has(x.id))}
function fineDriverLabel(fine){const driver=paieSalaries().find(x=>x.id===fine.salaryId);return driver?.name||'Non désigné'}
function recapStatusLabel(status,salarie,date,record){if(status==='present'&&canManageSalary()){const rate=record?.rateApplied??paieRateForDate(salarie,date)?.rate;if(rate==null)return 'Présent · tarif non défini';const amount=record?.amount!=null?Number(record.amount):recapAmount(status,record?.prime||0,salarie,date,rate);return paieMoney(amount??rate)}return RECAP_STATUTS.find(x=>x[0]===status)?.[1]||status}
const RECAP_STATUTS=[['present','Présent'],['flex','Flex'],['repos','Repos'],['abt','ABT'],['deplanifie','Déplanifié'],['plantage','Plantage'],['reformation','Reformation'],['cp','CP'],['at','AT'],['am','AM'],['conges-ss','Congés SS']];
const RECAP_ZERO=new Set(['flex','repos','abt','deplanifie','plantage','reformation']);
const RECAP_STATUS_ONLY=new Set(['cp','at','am','conges-ss']);
const RECAP_COLORS={present:'good',flex:'flex',repos:'neutral',abt:'neutral',deplanifie:'warn',plantage:'bad',reformation:'blue',cp:'purple',at:'red',am:'amber','conges-ss':'teal'};
function paiePointages(){return db.paie.pointages||(db.paie.pointages=[])}
function paieLeftDate(x){return x.status==='sorti'?(x.exitDate||null):paieExitStop(x)}
function recapRecHasData(r){return !!(r&&(r.status||r.plate||String(r.comment||'').trim()||(String(r.prime??'').trim()!==''&&Number(r.prime)!==0)||Object.values(r.samedayCycles||{}).some(Boolean)||Object.values(r.samedayCycleStates||{}).some(Boolean)))}
function recapRowLate(s,date){const l=paieLeftDate(s);if(!l||date<=l)return '';return `<span class="recap-late">${s.status==='sorti'?'Sorti le':'Dernier jour travaillé :'} ${esc(fmtDate(l))} · saisie à supprimer <button type="button" class="vr-link" data-recap-late-clear="${escapeAttr(s.id)}">Supprimer la saisie</button></span>`}
function recapStaffForDate(date,depot){return paieSalaries().filter(x=>{const lf=paieLeftDate(x),late=!!lf&&date>lf;if(late&&!paiePointages().some(r=>r.salaryId===x.id&&r.date===date&&recapRecDepot(r)===depot&&recapRecHasData(r)))return false;if(x.entryDate&&date<x.entryDate)return false;if(!late){if(x.exitDate&&date>x.exitDate)return false;if(x.status!=='active'&&!(['sorti','inactif','inactive'].includes(x.status)&&x.exitDate&&date<=x.exitDate))return false}return paieDepotAt(x,date)===depot||paiePointages().some(r=>r.salaryId===x.id&&r.date===date&&r.depot===depot)}).sort((a,b)=>((paieDepotAt(a,date)!==depot)-(paieDepotAt(b,date)!==depot))||(a.lastName||a.name||'').localeCompare(b.lastName||b.name||'','fr',{sensitivity:'base'})||(a.firstName||'').localeCompare(b.firstName||'','fr',{sensitivity:'base'}))}
function recapAmount(status,prime,salarie,date,rateSnapshot){if(RECAP_STATUS_ONLY.has(status))return null;if(RECAP_ZERO.has(status))return 0;if(status!=='present')return null;const rate=rateSnapshot==null?paieRateForDate(salarie,date)?.rate:rateSnapshot;return Math.round(((Number(rate)||0)+(Number(prime)||0))*100)/100}
function recapUpsert(salarie,date,status,prime=0,comment='',plate=''){const arr=paiePointages(),existing=arr.find(x=>x.salaryId===salarie.id&&x.date===date),snapshot=existing?.rateApplied??paieRateForDate(salarie,date)?.rate??null,amount=recapAmount(status,prime,salarie,date,snapshot),record={...(existing||{}),id:existing?.id||`pt-${salarie.id}-${date}`,salaryId:salarie.id,date,status,plate:normalizePlate(plate||existing?.plate||''),prime:status==='present'?(Number(prime)||0):0,rateApplied:status==='present'?snapshot:null,comment:String(comment||'').trim(),amount,updatedAt:new Date().toISOString()};if(existing)Object.assign(existing,record);else arr.push(record);return record}
function recapEntriesForDate(date,depot){const staff=recapStaffForDate(date,depot),ids=new Set(staff.map(x=>x.id));return paiePointages().filter(x=>x.date===date&&ids.has(x.salaryId)&&recapRecDepot(x)===depot)}
function recapSummary(date,depot){const staff=recapStaffForDate(date,depot),entries=recapEntriesForDate(date,depot),byId=new Map(entries.map(x=>[x.salaryId,x]));let present=0,flex=0,absent=0,total=0;for(const x of staff){const e=byId.get(x.id);if(!e)continue;if(e.status==='present')present++;else if(e.status){absent++;if(e.status==='flex')flex++}if(canManageSalary()&&e.amount!=null)total+=Number(e.amount)||0}return {present,flex,absent,total,entered:entries.filter(x=>recapEntryDone(x,depot)).length,staff:staff.length}}
function recapRecDepot(r){const s=paieSalaries().find(x=>x.id===r.salaryId);return r.depot||paieDepotAt(s,r.date)||''}
function recapRec(sid,date,depot){return paiePointages().find(x=>x.salaryId===sid&&x.date===date&&recapRecDepot(x)===depot)||null}
function recapOtherRecs(s,date,depot){return paiePointages().filter(x=>x.salaryId===s.id&&x.date===date&&recapRecDepot(x)!==depot)}
function recapPrestaLabel(r){const p=[];if(r.status==='present')p.push('Nextday');else if(r.status)p.push(recapStatusLabel(r.status));const cy=recapGridCycleKeys().filter(c=>recapGridCycleValue(r,c));if(cy.length)p.push('Sameday '+cy.join(', '));return p.length?p.join(' + '):'à saisir'}
function recapRowDepotInfo(s,date){const renfort=paieDepotAt(s,date)!==recapDepot,mine=recapRec(s.id,date,recapDepot),others=recapOtherRecs(s,date,recapDepot),lk=!!recapValidation(recapDepot,date);let h='';if(renfort)h+=`<span class="gp-renfort-badge">Renfort · ${esc(s.depot||'À affecter')}</span>${lk?'':`<button type="button" class="gp-renfort-x" data-recap-renfort-remove="${escapeAttr(s.id)}" title="Retirer du récap de ${escapeAttr(recapDepot)}" aria-label="Retirer ${escapeAttr(s.name||'salarié')} du récap de ${escapeAttr(recapDepot)}">×</button>`}`;others.forEach(o=>{h+=`<span class="gp-renfort-info">↗ Aussi sur ${esc(recapRecDepot(o))} · ${esc(recapPrestaLabel(o))}</span>`});const dbl=mine&&mine.status==='present'?others.find(o=>o.status==='present'):null;if(dbl)h+=`<span class="gp-renfort-warn">⚠ Nextday aussi compté sur ${esc(recapRecDepot(dbl))}</span>`;return h+recapSdFlag(s,date,mine)}
function recapWarnDouble(s,record,was){if(record.status==='present'&&!was){const o=recapOtherRecs(s,record.date,recapDepot).find(x=>x.status==='present');if(o)toast(`${s.name} est déjà Présent (Nextday) sur ${recapRecDepot(o)} ce jour : deux Nextday seront comptés.`)}}
function recapRenfortButton(depot,date){return recapValidation(depot,date)?'':'<button type="button" class="btn light" id="recap-renfort-add" title="Ajouter un chauffeur en renfort" aria-label="Ajouter un chauffeur en renfort"><i data-lucide="user-plus" aria-hidden="true"></i> Renfort</button>'}
function recapRenfortCandidates(date,depot){const here=new Set(recapStaffForDate(date,depot).map(x=>x.id));return paieSalaries().filter(x=>{if(here.has(x.id))return false;if(paieExitStop(x)&&date>paieExitStop(x))return false;if(x.entryDate&&date<x.entryDate)return false;if(x.exitDate&&date>x.exitDate)return false;if(x.status!=='active'&&!(['sorti','inactif','inactive'].includes(x.status)&&x.exitDate&&date<=x.exitDate))return false;return x.depot!==depot}).sort((a,b)=>(a.lastName||a.name||'').localeCompare(b.lastName||b.name||'','fr',{sensitivity:'base'})||(a.firstName||'').localeCompare(b.firstName||'','fr',{sensitivity:'base'}))}
function recapRenfortModal(){if(recapValidation(recapDepot,recapDate))return toast('Journée validée : rouvrez-la pour ajouter un chauffeur.');const list=recapRenfortCandidates(recapDate,recapDepot),opts=list.map(x=>`<option value="${escapeAttr(x.id)}">${esc(x.name)} · ${esc(x.depot||'À affecter')}</option>`).join(''),dl=new Date(`${recapDate}T12:00:00`).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});openModal('Ajouter un chauffeur en renfort',`<form id="renfort-form" class="form-grid"><label class="full">Chauffeur<select name="driver" required>${opts?`<option value="">Choisir…</option>${opts}`:'<option value="">Aucun chauffeur disponible</option>'}</select></label><div class="full gp-kv"><span><i data-lucide="map-pin" aria-hidden="true"></i>Dépôt d’accueil : ${esc(recapDepot)}</span><span><i data-lucide="calendar" aria-hidden="true"></i>${esc(dl)}</span></div><div id="sd-tarif-zone" class="full"></div><div class="gp-renfort-note gp-info b full"><i data-lucide="info" aria-hidden="true"></i><span>Le chauffeur reste affecté à son dépôt d’origine. Il apparaît dans le récap de ${esc(recapDepot)} pour cette journée uniquement ; ce qui est saisi ici compte pour ${esc(recapDepot)}.</span></div></form>`,`<button class="btn light" data-close>Annuler</button><button class="btn primary" id="renfort-save" ${opts?'':'disabled'}>Ajouter au récap du jour</button>`,'Renfort d’un jour · le dépôt d’origine ne change pas');sdZoneInit(()=>list.find(y=>y.id===$('#renfort-form').elements.driver.value),recapDepot,recapDate);$('#renfort-save').onclick=()=>{const id=$('#renfort-form').elements.driver.value,x=list.find(y=>y.id===id);if(!x)return toast('Choisissez un chauffeur.');const sd=sdTarifRead(x,recapDate);if(sd.error)return toast(sd.error);if(recapValidation(recapDepot,recapDate))return toast('Journée validée.');if(recapRec(x.id,recapDate,recapDepot))return toast('Déjà présent dans ce récap.');paiePointages().push({id:`pt-${x.id}-${recapDate}-${recapDepot}`,depot:recapDepot,salaryId:x.id,date:recapDate,prime:'',comment:'',plate:'',status:'',samedayCycles:{},rateApplied:null,updatedAt:new Date().toISOString()});sdTarifApply(x,recapDate,sd);save();closeModal();render();toast(`${x.name} ajouté en renfort sur ${recapDepot}.`)}}
function sdMissingCycles(s,date){return SAMEDAY_CYCLES.filter(c=>!samedayRateAt(s,c,date))}
function sdZoneHtml(s,depot,date){if(!s||!servicesForDepot(depot).includes('SAMEDAY'))return '';const miss=sdMissingCycles(s,date);if(!miss.length)return '';const lead=miss.length===SAMEDAY_CYCLES.length?`<b>${esc(s.name)} n’a pas de tarif Sameday.</b> Sans tarif, ses cycles à ${esc(depot)} ne seront pas rémunérés.`:`<b>${esc(s.name)} n’a pas de tarif Sameday pour les cycles ${miss.join(', ')}.</b> Ces cycles ne seront pas rémunérés sans tarif.`;if(!canManageSalary())return `<div class="gp-sd-warn" role="status"><span aria-hidden="true">⚠</span><span>${lead} Un Responsable ou un RH doit le renseigner sur sa fiche.</span></div>`;return `<div class="gp-sd-warn" role="status"><span aria-hidden="true">⚠</span><span>${lead} Saisissez-le ci-dessous (il sera enregistré sur sa fiche) ou plus tard.</span></div><div class="gp-sd-tarif"><h4>Tarif Sameday · à partir du ${fmtDate(date)}</h4><div class="gp-sd-cycles">${miss.map(c=>`<label class="recap-cycle-check"><input type="checkbox" data-sd-cycle="${c}" checked><span>${c}</span></label>`).join('')}</div><label>Salaire semaine (€)<input id="sd-weekly" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0,00"></label><label>Dimanche et jours fériés (€)<input id="sd-sunday" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0,00"></label></div>`}
function sdZoneInit(getter,depot,date){const sel=document.querySelector('#modal-root select[name=driver]'),upd=()=>{const el=$('#sd-tarif-zone');if(el)el.innerHTML=sdZoneHtml(getter(),depot,date)};if(sel)sel.addEventListener('change',upd);upd()}
function sdTarifRead(s,date){const w=$('#sd-weekly'),u=$('#sd-sunday');if(!s||!w||!u)return {};const cycles=[...document.querySelectorAll('[data-sd-cycle]:checked')].map(x=>x.dataset.sdCycle),wv=String(w.value).trim().replace(',','.'),uv=String(u.value).trim().replace(',','.');if(wv===''&&uv==='')return {};if(wv===''||uv===''||!Number.isFinite(Number(wv))||!Number.isFinite(Number(uv))||Number(wv)<0||Number(uv)<0)return {error:'Tarif Sameday : renseignez les deux montants (semaine et dimanche / jours fériés), ou laissez les deux vides.'};if(!cycles.length)return {error:'Tarif Sameday : cochez au moins un cycle.'};return {cycles,weekly:Number(wv),sunday:Number(uv)}}
function sdTarifApply(s,date,sd){if(!s||!sd||!sd.cycles)return;sd.cycles.forEach(c=>samedayAddSalaryRate(s,role,{cycle:c,effectiveDate:date,weeklyRate:sd.weekly,sundayRate:sd.sunday}));s.updatedAt=new Date().toISOString();save()}
function recapSdFlag(s,date,rec){if(!rec||!recapGridCycleKeys().some(c=>recapGridCycleValue(rec,c)&&!samedayRateAt(s,c,date)))return '';return canManageSalary()?`<button type="button" class="gp-sd-flag" data-recap-sd-fiche="${escapeAttr(s.id)}" title="Ouvrir la fiche pour saisir le tarif Sameday">⚠ Tarif Sameday manquant · Saisir</button>`:'<span class="gp-sd-flag is-info">⚠ Tarif Sameday à renseigner (Responsable / RH)</span>'}
function bindRecapSdFlags(){document.querySelectorAll('[data-recap-sd-fiche]').forEach(b=>b.onclick=e=>{e.stopPropagation();selectedSalarie=b.dataset.recapSdFiche;nav('paie-employee')})}
function recapSdFlagRefresh(row,s,rec){const cell=row.querySelector('.recap-person');if(!cell)return;cell.querySelectorAll('.gp-sd-flag').forEach(x=>x.remove());const h=recapSdFlag(s,recapDate,rec);if(h){cell.insertAdjacentHTML('beforeend',h);bindRecapSdFlags()}}
function bindRecapRenfort(){bindRecapSdFlags();const add=$('#recap-renfort-add');if(add)add.onclick=recapRenfortModal;document.querySelectorAll('[data-recap-renfort-remove]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(recapValidation(recapDepot,recapDate))return toast('Journée validée.');const id=b.dataset.recapRenfortRemove,rec=recapRec(id,recapDate,recapDepot);if(!rec||!rec.depot)return;const used=rec.status||rec.prime!==''&&rec.prime!=null||rec.comment||rec.plate||recapGridCycleKeys().some(c=>recapGridCycleValue(rec,c))||(rec.vehicles&&rec.vehicles.length);if(used)return toast('Videz d’abord la ligne (statut, cycles, plaque, prime, commentaire) avant de la retirer.');const arr=paiePointages(),i=arr.indexOf(rec);if(i>=0){arr.splice(i,1);save();render();toast('Chauffeur retiré du récap.')}})}
function recapDayInput(s,date,depot=recapDepot){return recapRec(s.id,date,depot)}
function recapRfNameTag(s){return paieDepotAt(s,recapDate)!==recapDepot?`<small class="gp-rf-name" title="Renfort — dépôt d’origine ${escapeAttr(s.depot||'autre dépôt')}">↗ Renfort</small>`:''}
function recapEmployeeName(s){return esc([s.firstName,s.lastName].filter(Boolean).join(' ')||s.name||'Salarié')}
function recapGridCycleKeys(){return [...SAMEDAY_CYCLES]}
function recapGridCycleValue(record,cycle){if(!record)return false;const source=record.samedayCycles||record.cycles||record.zones||{};if(Array.isArray(source))return source.some(x=>String(x).toUpperCase()===cycle);if(source&&Object.prototype.hasOwnProperty.call(source,cycle))return source[cycle]!==false&&source[cycle]!=null&&source[cycle]!==''&&source[cycle]!==0;if(String(record.cycle||record.samedayCycle||'').toUpperCase()===cycle)return true;return cycle==='A'&&(record.workActivity==='SAMEDAY'||!!record.serviceTypeId)}
function recapIsHoliday(date){const y=Number(String(date).slice(0,4)),fixed=new Set([`${y}-01-01`,`${y}-05-01`,`${y}-05-08`,`${y}-07-14`,`${y}-08-15`,`${y}-11-01`,`${y}-11-11`,`${y}-12-25`]);if(fixed.has(date))return true;const a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=(h+l-7*m+114)%31+1;for(const offset of [1,39,50]){const easter=new Date(y,month-1,day);easter.setDate(easter.getDate()+offset);if(easter.toISOString().slice(0,10)===date)return true}return false}
function recapLocalIso(off=0){const d=new Date();d.setDate(d.getDate()+off);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function recapDayLabel(date){return new Date(`${date}T12:00:00`).toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'2-digit'})}
function recapRemLabel(x){return x.n?`${x.n} / ${x.total}`:'non commencé'}
function recapReminders(){const out={yest:[],late:[],strip:[]};try{recapDepotChoices().forEach(depot=>{for(let k=1;k<=Math.max(7,new Date().getDate()-1);k++){const date=recapLocalIso(-k),staff=recapStaffForDate(date,depot);if(!staff.length)continue;const n=recapEntriesForDate(date,depot).filter(x=>recapEntryDone(x,depot)).length,total=staff.length,fcm=recapFcMissing(depot,date).length,done=!!recapValidation(depot,date)||(n>=total&&!fcm);if(k===1)out.strip.push({depot,date,n,total,done});if(done)continue;(k===1?out.yest:out.late).push({depot,date,n,total,fc:!!fcm})}});out.late.sort((a,b)=>a.date.localeCompare(b.date)||a.depot.localeCompare(b.depot))}catch(e){}return out}
function recapVeilleStrip(){const s=recapReminders().strip;if(!s.length)return '';const all=s.every(x=>x.done);return `<section class="rv-veille" aria-label="Saisie de la veille"><div class="rv-veille-head"><b>Saisie de la veille · ${esc(recapDayLabel(s[0].date))}</b><span class="${all?'ok':''}">${all?'Tout est à jour':'À compléter aujourd’hui avant minuit'}</span></div><div class="rv-veille-grid">${s.map(x=>`<div class="rv-dp${x.done?' is-done':''}" data-ov-recap="${escapeAttr(x.depot)}" data-ov-date="${x.date}" tabindex="0" role="button" aria-label="Ouvrir le récap de ${escapeAttr(x.depot)} du ${escapeAttr(recapDayLabel(x.date))}"><b>${esc(x.depot)}</b><div><span>${x.n} / ${x.total} saisis</span>${pill(x.done?'Complet':'À compléter',(x.done?'good':'warn')+' st-up')}</div><i class="rv-bar"><i style="width:${Math.round(100*Math.min(x.n,x.total)/x.total)}%"></i></i></div>`).join('')}</div></section>`}
function recapRemGroups(r){const g=new Map();[...r.late.map(x=>({...x,late:true})),...r.yest.map(x=>({...x,late:false}))].forEach(x=>{if(!g.has(x.depot))g.set(x.depot,[]);g.get(x.depot).push(x)});g.forEach(l=>l.sort((a,b)=>a.date.localeCompare(b.date)));return g}
function recapShortDay(date){return new Date(`${date}T12:00:00`).toLocaleDateString('fr-FR',{weekday:'short',day:'2-digit',month:'2-digit'})}
function recapListModal(){const g=recapRemGroups(recapReminders()),total=[...g.values()].reduce((a,l)=>a+l.length,0);if(!total){toast('Aucune journée à compléter.');return}openModal('Journées à compléter',`<div class="rv-list">${[...g.entries()].map(([dep,l])=>`<section class="rv-dep"><div class="rv-dep-h"><b>${esc(dep)}</b><span>${l.length} journée${l.length>1?'s':''}</span></div><div class="rv-chips">${l.map(x=>`<button type="button" class="rv-chip ${x.late?'r':'a'}" data-rv-day="${x.date}" data-rv-depot="${escapeAttr(dep)}" title="${x.late?'Délai dépassé':'À compléter aujourd’hui'}">${esc(recapShortDay(x.date))}<small>${x.n} / ${x.total}${x.fc?' · FC':''}</small></button>`).join('')}</div></section>`).join('')}</div>`,`<button class="btn primary" data-close>Fermer</button>`,`${total} journée${total>1?'s':''} sur ${g.size} dépôt${g.size>1?'s':''} · cliquez sur une date pour la saisir`);document.querySelectorAll('#modal-root [data-rv-day]').forEach(b=>b.onclick=()=>{const dep=b.dataset.rvDepot,day=b.dataset.rvDay;closeModal();paieOvGoRecap(dep,day)})}
function recapAllBanner(g){const all=[...g.values()].flat(),late=all.filter(x=>x.late),oldest=[...all].sort((a,b)=>a.date.localeCompare(b.date))[0],deps=[...g.entries()].map(([d,l])=>`${esc(d)} : ${l.length}`),shown=deps.slice(0,5).join(' · ')+(deps.length>5?` · +${deps.length-5}`:'');return `<div class="rv-bans" role="status"><div class="rv-ban${late.length?' is-late':''}"><div><b>${all.length} journée${all.length>1?'s':''} à compléter sur ${g.size} dépôt${g.size>1?'s':''}</b><small>${shown} — ${late.length?`dont ${late.length} en retard (délai dépassé).`:'à compléter aujourd’hui avant minuit.'}</small></div><div class="rv-acts"><button type="button" class="rv-link" data-rv-list="1">Voir la liste</button><button type="button" class="btn primary small" data-recap-goto="${oldest.date}" data-recap-depot="${escapeAttr(oldest.depot)}">${late.length?'Compléter la plus ancienne':'Compléter hier'}</button></div></div></div>`}
function recapChefBanners(){const g=recapRemGroups(recapReminders());if(!g.size)return '';if(role!=='chef')return recapAllBanner(g);return `<div class="rv-bans" role="status">${[...g.entries()].map(([dep,l])=>{const late=l.filter(x=>x.late),o=l[0],oldest=o.late?o:null,hasYest=l.some(x=>!x.late),goto=oldest||o;let title,sub;if(late.length===1&&l.length===1)title=`Il manque la saisie du ${esc(recapDayLabel(o.date))} à ${esc(dep)} (${o.n?`${o.n} sur ${o.total}`:'aucune saisie'})`,sub='Le délai est dépassé : merci de la compléter dès que possible.';else if(!late.length)title=`Saisie d’hier (${esc(recapDayLabel(o.date))}) à ${esc(dep)} : ${o.n} sur ${o.total}`,sub='À compléter aujourd’hui avant minuit.';else title=`${esc(dep)} : ${l.length} journée${l.length>1?'s':''} à compléter, la plus ancienne est le ${esc(recapDayLabel(o.date))}`,sub=`Le délai est dépassé pour ${late.length} d’entre elles${hasYest?' ; hier est à compléter avant minuit':''}. Complétez-les dans l’ordre.`;return `<div class="rv-ban${late.length?' is-late':''}"><div><b>${title}</b><small>${sub}</small></div><div class="rv-acts">${l.length>1?'<button type="button" class="rv-link" data-rv-list="1">Voir la liste</button>':''}<button type="button" class="btn primary small" data-recap-goto="${goto.date}" data-recap-depot="${escapeAttr(dep)}">${late.length?`Compléter le ${goto.date.slice(8)}/${goto.date.slice(5,7)}`:'Compléter hier'}</button></div></div>`}).join('')}</div>`}
function recapNavBadge(){const r=recapReminders(),n=r.late.length+r.yest.length;return n?` <b class="nav-count" id="nav-recap-count" title="Saisie à compléter">${n}</b>`:''}
const RECAP_QUICK=[['present','Présent'],['repos','Repos']];
function recapQuickHtml(s,selected,lk){const nm=escapeAttr(s.name||'salarié'),others=RECAP_STATUTS.filter(x=>!RECAP_QUICK.some(q=>q[0]===x[0])),other=others.some(x=>x[0]===selected);return `<div class="rq" role="group" aria-label="Statut Nextday rapide — ${nm}">${RECAP_QUICK.filter(q=>recapNd(recapDepot)||q[0]!=='present'||selected===q[0]).map(([v,l])=>`<button type="button" class="rq-b${selected===v?' is-on':''}" data-recap-quick="${v}" aria-pressed="${selected===v}"${lk}>${l}</button>`).join('')}<select class="rq-other${other?' is-on':''}" data-recap-other${lk} aria-label="Autre statut — ${nm}"><option value="">Autre</option>${others.map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('')}</select></div>`}
function recapQuickSync(row){const m=row.querySelector('[data-recap-status]');if(!m)return;const v=m.value;row.querySelectorAll('[data-recap-quick]').forEach(b=>{const on=b.dataset.recapQuick===v;b.classList.toggle('is-on',on);b.setAttribute('aria-pressed',String(on))});const o=row.querySelector('[data-recap-other]');if(o){const has=!!v&&[...o.options].some(x=>x.value===v);o.value=has?v:'';o.classList.toggle('is-on',has)}}
function recapSummaryHtml(summary,date,depot,showSameday,attr){const j=recapView==='jour';return `<section class="recap-summary"${attr} aria-live="polite"><div${recapNd(depot)?'':' hidden'}><strong data-recap-kpi="present">${summary.present}</strong><span>${j?'présents':'Présents'}</span></div><div title="Autres statuts"${recapNd(depot)?'':' hidden'}><strong data-recap-kpi="absent">${summary.absent}</strong><span>${j?'autres statuts':'Autres statuts'}</span></div>${canManageSalary()?`<div class="recap-total"><strong data-recap-kpi="total">${paieMoney(summary.total)}</strong><span>${j?'total du jour':'Total du jour'}</span></div>`:''}</section>`}
function recapMonthStrip(date,depot){const month=String(date).slice(0,7),[yy,mm]=month.split('-').map(Number),nd=new Date(yy,mm,0).getDate(),today=recapLocalIso(0),yest=recapLocalIso(-1);const cells=[];for(let d=1;d<=nd;d++){const ds=`${month}-${String(d).padStart(2,'0')}`,staff=recapStaffForDate(ds,depot),total=staff.length,n=recapEntriesForDate(ds,depot).filter(x=>recapEntryDone(x,depot)).length,val=!!recapValidation(depot,ds);let st;if(ds>today)st='f';else if(!total&&!val)st='f';else if(val||(n>=total&&!recapFcMissing(depot,ds).length))st='v';else if(ds===today)st='t';else if(ds===yest)st='a';else st='r';const lbl={v:'complet ou validé',a:'hier, à compléter',r:'en retard',t:'aujourd’hui, en cours',f:'à venir'}[st];cells.push(`<button type="button" class="rv-dy ${st}${ds===date?' is-sel':''}" data-recap-day="${ds}" aria-label="${escapeAttr(recapDayLabel(ds))} : ${lbl}"${ds===date?' aria-current="date"':''} title="${escapeAttr(recapDayLabel(ds))} · ${lbl}">${d}</button>`)}return `<section class="rv-strip" aria-label="Jours du mois"><div class="rv-strip-h"><span class="rv-strip-t">${paieMonthNav('recap-month',month)}<span>${esc(depot)} · cliquez sur un jour</span></span><span class="rv-leg"><span><i class="v"></i>complet / validé</span><span><i class="a"></i>hier à compléter</span><span><i class="r"></i>en retard</span><span><i class="f"></i>à venir</span></span></div><div class="rv-days" style="--rv-n:${nd}">${cells.join('')}</div></section>`}
function recapIsSundayOrHoliday(date){return new Date(`${date}T12:00:00`).getDay()===0||recapIsHoliday(date)}
function recapRateForDay(history,date,cycle){const valid=(history||[]).filter(x=>x&&x.effectiveDate&&x.effectiveDate<=date&&(!cycle||String(x.cycle||'').toUpperCase()===cycle)).sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate));const rate=valid[0];if(!rate)return null;const amount=recapIsSundayOrHoliday(date)?rate.sundayRate:rate.weeklyRate;return amount==null||String(amount).trim()===''||!Number.isFinite(Number(amount))?null:Number(amount)}
function recapNextdayRate(s,date){return recapRateForDay(s?.salaryHistory,date,null)}
function recapSamedayCycleRate(s,date,cycle){const entry=samedayRateAt(s,cycle,date);return entry?recapRateForDay([entry],date,cycle):null}
function recapCombinedDayTotal(s,date,record){const status=record?.status||'',selected=recapGridCycleKeys().filter(c=>recapGridCycleValue(record,c));let total=0;if(status==='present'){const rate=recapNextdayRate(s,date);if(rate==null)return null;total+=rate}for(const cycle of selected){const rate=recapSamedayCycleRate(s,date,cycle);if(rate==null)return null;total+=rate}const raw=String(record?.prime??'').trim().replace(',','.');const prime=raw===''?0:Number(raw);if(!Number.isFinite(prime))return null;if(!status&&!selected.length&&raw==='')return null;return Math.round((total+prime)*100)/100}
