function recapSamedayVisible(depot,date){if(servicesForDepot(depot).includes('SAMEDAY'))return true;return recapStaffForDate(date,depot).some(s=>{const r=recapDayInput(s,date);return recapGridCycleKeys().some(c=>recapGridCycleValue(r,c))})}
function recapSamedayNote(depot,date,shown){if(servicesForDepot(depot).includes('SAMEDAY'))return '';const name=esc(depot||'ce dépôt');if(shown)return `<p class="recap-sameday-note is-warning" role="status"><span class="recap-sameday-note-icon" aria-hidden="true">!</span><span><b>Sameday n’est pas activé pour ${name},</b> mais des cycles ont déjà été saisis à cette date. Ils restent affichés pour pouvoir être vérifiés.</span></p>`;return `<p class="recap-sameday-note" role="note"><span class="recap-sameday-note-icon" aria-hidden="true">i</span><span><b>Sameday n’est pas activé pour ${name}.</b> Les cycles A, E, B, C, D s’afficheront dès son activation.</span>${canAccessAdmin()?'<button type="button" class="link-button" data-page="admin-depots">Administration › Dépôts</button>':''}</p>`}
