const RECAP_VEH_REASONS=[['panne','Panne'],['echange','Échange'],['autre','Autre']];
const RECAP_SWAP_SVG='<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 3 4 7l4 4"/><path d="M4 7h16"/><path d="m16 21 4-4-4-4"/><path d="M20 17H4"/></svg>';
/* Véhicules du jour. Un pointage garde « plate » (véhicule Nextday en cours, champ du tableau) et, s'il y a eu un changement,
   « vehicles » : [{plate, use:['ND','A',…], since:'HH:MM', ended, endedAt, reason:'panne'|'echange'|'autre', note}].
   Sans « vehicles », la plaque seule vaut un véhicule unique (données existantes inchangées).
   Migration Supabase : table pointage_vehicules (pointage_id, plate, use[], since, ended, ended_at, reason, note). */
function recapVehicles(rec){if(!rec)return [];if(Array.isArray(rec.vehicles)&&rec.vehicles.length)return rec.vehicles;const p=normalizePlate(rec.plate||'');return p?[{plate:p,use:['ND'],since:'',ended:false}]:[]}
function recapRecordPlates(rec){return [...new Set([normalizePlate(rec?.plate||''),...(rec&&Array.isArray(rec.vehicles)?rec.vehicles.map(v=>normalizePlate(v.plate||'')):[])].filter(Boolean))]}
function recapVehUseLabel(use){const u=Array.isArray(use)?use:[],cycles=recapGridCycleKeys().filter(c=>u.includes(c));return [u.includes('ND')?'Nextday':'',cycles.length?`Sameday ${cycles.join(', ')}`:''].filter(Boolean).join(' · ')||'—'}
function recapPlainName(s){return [s?.firstName,s?.lastName].filter(Boolean).join(' ')||s?.name||'Salarié'}
function recapTime(t){return /^\d{2}:\d{2}$/.test(t||'')?t.replace(':',' h '):''}
function recapVehReason(v){return ((RECAP_VEH_REASONS.find(r=>r[0]===v.reason)||[])[1]||'Remplacé')}
function recapVehiclesTip(rec,title){return `<b>${esc(title)}</b>${recapVehicles(rec).map(v=>`<span class="ln"><span>${v.ended?`<s>${esc(v.plate)}</s>`:esc(v.plate)}</span><span class="${v.ended&&v.reason==='panne'?'bad':''}">${v.ended?esc(recapVehReason(v).toLowerCase()+(v.endedAt?' '+recapTime(v.endedAt):'')):esc(recapVehUseLabel(v.use)+(v.since?' · dès '+recapTime(v.since):''))}</span></span>`).join('')}`}
function recapVehicleBadge(rec){const n=recapVehicles(rec).length;if(n<2)return '';return `<button type="button" class="rv-badge" data-recap-vehicles data-rtip aria-label="${n} véhicules ce jour, voir le détail">${RECAP_SWAP_SVG}<span aria-hidden="true">${n}</span><span class="rtip-src" hidden>${recapVehiclesTip(rec,'Véhicules du jour')}</span></button>`}
function recapApplyVehicleChange(rec,before,now,o){const list=recapVehicles(rec).map(v=>({...v,use:[...(v.use||[])]}));if(!list.some(v=>v.plate===before))list.unshift({plate:before,use:['ND'],since:'',ended:false});const nd=o.use.includes('ND'),old=list.find(v=>v.plate===before&&!v.ended);if(old&&(nd||o.reason==='panne')){old.ended=true;old.endedAt=o.time||'';old.reason=o.reason;if(o.note)old.note=o.note}else if(old){old.use=old.use.filter(u=>!o.use.includes(u));if(!old.use.length)old.use=['ND']}list.forEach(v=>{if(v===old||v.ended||v.plate===now)return;const left=v.use.filter(u=>!o.use.includes(u));if(left.length!==v.use.length){if(left.length)v.use=left;else{v.ended=true;v.endedAt=o.time||'';v.reason=o.reason}}});const target=list.find(v=>v.plate===now&&!v.ended);if(target)target.use=[...new Set([...target.use,...o.use])];else list.push({plate:now,use:[...o.use],since:o.time||'',ended:false});rec.vehicles=list;rec.plate=nd?now:before;rec.updatedAt=new Date().toISOString()}
