openModal('Plaque différente',`<div class="rv-modal"><div class="rv-compare"><span class="rv-tag">${esc(before)}</span>${RECAP_SWAP_SVG}<span class="rv-tag is-new">${esc(now)}</span><span>Une plaque était déjà saisie pour cette journée.</span></div><label class="rv-option is-on"><input type="radio" name="rv-kind" value="change" checked><span><b>Changement de véhicule dans la journée</b>Les deux véhicules sont conservés pour cette journée.</span></label><div class="rv-sub" id="rv-sub"><div class="rv-row"><label class="rv-field rv-time">Heure<input type="time" id="rv-time" value="${nowTime}"></label><div class="rv-field"><span>Motif</span><div class="rv-chips" role="group" aria-label="Motif">${chips('reason',RECAP_VEH_REASONS,['panne'])}</div></div></div>${uses.length>1?`<div class="rv-field"><span>Le nouveau véhicule sert pour</span><div class="rv-chips" role="group" aria-label="Activité du nouveau véhicule">${chips('use',uses,['ND'])}</div></div>`:''}<div id="rv-incident-wrap">${veh?`<label class="rv-check"><input type="checkbox" id="rv-incident" checked><span><b>Signaler un incident sur ${esc(before)}</b>Ouvre le formulaire d’incident de la Flotte, prérempli, pour suivre la panne côté parc.</span></label>`:`<p class="rv-hint">${esc(before)} n’est pas un véhicule du parc : aucun incident ne sera créé côté Flotte.</p>`}</div><label class="rv-field">Commentaire (facultatif)<input type="text" id="rv-note" maxlength="200" placeholder="Ex. voyant moteur, remorqué au dépôt…"></label></div><label class="rv-option"><input type="radio" name="rv-kind" value="fix"><span><b>Correction d’une erreur de saisie</b>${esc(now)} remplace ${esc(before)}, qui n’est pas conservée.</span></label></div>`,'<button class="btn light" data-close>Annuler</button><button class="btn primary" id="rv-save">Enregistrer</button>',`${esc(recapPlainName(s))} · ${esc(label)} · ${esc(recapDepot)}`);
const kindOf=()=>document.querySelector('[name="rv-kind"]:checked')?.value||'change',sync=()=>{const k=kindOf();document.querySelectorAll('.rv-option').forEach(o=>o.classList.toggle('is-on',o.querySelector('input').checked));const sub=$('#rv-sub');if(sub)sub.hidden=k!=='change';const reason=document.querySelector('[data-rv-reason].on')?.dataset.rvReason;const wrap=$('#rv-incident-wrap');if(wrap)wrap.hidden=reason!=='panne'};document.querySelectorAll('[name="rv-kind"]').forEach(r=>r.onchange=sync);document.querySelectorAll('[data-rv-reason]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-rv-reason]').forEach(x=>{const on=x===b;x.classList.toggle('on',on);x.setAttribute('aria-pressed',on)});sync()});document.querySelectorAll('[data-rv-use]').forEach(b=>b.onclick=()=>{const on=!b.classList.contains('on');b.classList.toggle('on',on);b.setAttribute('aria-pressed',on)});sync();
