function recapVehiclesModal(id){const s=paieSalaries().find(x=>x.id===id),rec=recapRec(id,recapDate,recapDepot);if(!s||!rec)return;const lk=!!recapValidation(recapDepot,recapDate),list=recapVehicles(rec),keep=rec.plate||list.filter(v=>!v.ended).map(v=>v.plate).pop()||'';openModal('Véhicules du jour',`<ul class="rv-list">${list.map(v=>`<li class="${v.ended?'is-ended':''}"><span class="rv-tag">${esc(v.plate)}</span><span><b class="${v.ended&&v.reason==='panne'?'bad':''}">${v.ended?esc(recapVehReason(v))+(v.endedAt?' à '+recapTime(v.endedAt):''):esc(recapVehUseLabel(v.use))}</b>${!v.ended&&v.since?`<small>Depuis ${recapTime(v.since)}</small>`:''}${v.note?`<small>${esc(v.note)}</small>`:''}</span></li>`).join('')}</ul>${lk?'<p class="muted" style="margin:12px 0 0">Journée validée : la liste ne peut plus être modifiée.</p>':''}`,lk||!keep?'<button class="btn primary" data-close>Fermer</button>':`<button class="btn light" id="rv-reset">Ne garder que ${esc(keep)}</button><button class="btn primary" data-close>Fermer</button>`,`${esc(recapPlainName(s))} · ${new Date(`${recapDate}T12:00:00`).toLocaleDateString('fr-FR')}`);const reset=$('#rv-reset');if(reset)reset.onclick=()=>{delete rec.vehicles;rec.plate=keep;rec.updatedAt=new Date().toISOString();save();closeModal();toast(`Historique effacé : seul ${keep} est conservé.`)}}
function recapBindVehicles(){recapUpdateRoutes();if(recapView==='jour')document.querySelectorAll('.recap-unified-row').forEach(row=>{const inp=row.querySelector('[data-recap-plate]');if(!inp||inp.disabled)return;const saved=()=>normalizePlate(recapRec(row.dataset.recapRow,recapDate,recapDepot)?.plate||'');inp.dataset.before=saved();inp.addEventListener('focus',()=>{inp.dataset.before=saved()});inp.addEventListener('change',()=>{const before=inp.dataset.before||'',now=normalizePlate(inp.value);if(before&&now&&before!==now)recapPlateChange(row,before,now);else inp.dataset.before=now})});document.querySelectorAll('[data-recap-vehicles]').forEach(b=>b.onclick=()=>recapVehiclesModal(b.closest('[data-recap-row]')?.dataset.recapRow));recapTipInit()}
/* Info-bulle flottante (survol ou focus d'un élément [data-rtip] contenant un .rtip-src) : n'est pas coupée par les tableaux défilants. */
function recapTipInit(){if(window.__gpTip)return;window.__gpTip=true;const tip=document.createElement('div');tip.className='gp-tip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.appendChild(tip);let host=null;const hide=()=>{host=null;tip.hidden=true};const show=el=>{const src=el.querySelector('.rtip-src');if(!src)return hide();host=el;tip.innerHTML=src.innerHTML;tip.hidden=false;const r=el.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;let top=r.top-h-10,below=false;if(top<8){top=r.bottom+10;below=true}const left=Math.min(Math.max(8,r.left+r.width/2-w/2),window.innerWidth-w-8);tip.style.top=`${Math.round(top)}px`;tip.style.left=`${Math.round(left)}px`;tip.style.setProperty('--arrow',`${Math.round(r.left+r.width/2-left)}px`);tip.classList.toggle('is-below',below)};document.addEventListener('mouseover',e=>{const el=e.target.closest?.('[data-rtip]');if(el){if(el!==host)show(el)}else if(host)hide()});document.addEventListener('focusin',e=>{const el=e.target.closest?.('[data-rtip]');if(el)show(el);else if(host)hide()});document.addEventListener('focusout',hide);window.addEventListener('scroll',hide,true);document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});document.addEventListener('click',e=>{if(host&&!e.target.closest?.('[data-rtip]'))hide()})}
function recapPeriodTools(){return `<div class="recap-period-tools"><div class="recap-period-tabs" role="group" aria-label="Organisation du récapitulatif"><button type="button" data-recap-period-mode="salaries" class="${recapPeriodMode==='salaries'?'active':''}" aria-pressed="${recapPeriodMode==='salaries'}">Par salarié</button><button type="button" data-recap-period-mode="vehicules" class="${recapPeriodMode==='vehicules'?'active':''}" aria-pressed="${recapPeriodMode==='vehicules'}">Par véhicule</button></div><button type="button" class="recap-display-toggle" id="recap-display-toggle" aria-pressed="${recapDisplay==='plaques'}">Afficher : <b>${recapDisplay==='plaques'?'Plaques':'Statut'}</b></button><label class="recap-search-field">Rechercher plaque ou chauffeur<input type="search" id="recap-search" value="${escapeAttr(recapSearch)}" placeholder="Ex. AB-123-CD ou Alex"></label></div>`}
/* Vue Mois : une case = un jour. Nextday : montant du jour (tarif + prime) ; Sameday : total des cycles. Le détail s'affiche au survol. */
/* Routes : 1 salarié Présent = 1 route Nextday ; 1 cycle Sameday coché = 1 route de ce cycle. Ce sont des quantités : visibles par tous les rôles. */
function recapRoutesLabel(n){return `${n} route${n>1?'s':''}`}
function recapRoutesDetail(nd,cyc,showSd,ndOn){const sd=cyc.reduce((a,b)=>a+b,0);return showSd?`${ndOn===false?'':nd+' Nextday · '}${sd} Sameday (${recapGridCycleKeys().map((c,i)=>`${c} ${cyc[i]}`).join(', ')})`:`${nd} Nextday`}
