function recapRoutesFoot(showSd){const cyc=showSd?recapGridCycleKeys():[];return `<tfoot class="rr-foot"><tr><th scope="row">Routes du jour</th>${recapNd(recapDepot)?'<td><b data-recap-routes="nd">0</b><small>Nextday</small></td>':''}${cyc.map(c=>`<td><b data-recap-routes-cycle="${c}">0</b></td>`).join('')}<td colspan="4" class="rr-foot-sum" data-recap-routes="sum"></td></tr></tfoot>`}
