function paieRecapMensuel(){const data=recapMensuelData(),rows=recapMensuelFiltered(data),hidden=recapMensuelFiltered(data,true).length-rows.length,emptyN=data.rows.filter(e=>e.key==='vide').length,inc=rows.filter(e=>e.key==='incomplet'),todoN=inc.reduce((a,e)=>a+e.todo.size,0),missN=inc.filter(e=>e.missing.size).length,draftN=inc.filter(e=>e.drafts.length).length,sel=rows.find(e=>e.s.id===recapMens.sel)||inc[0]||rows[0],z=v=>v?paieMoney(v):'—',sg=v=>v?(v>0?`+${paieMoney(v)}`:paieMoney(v)):'—',tot=k=>rows.reduce((a,e)=>a+e[k],0),rec=e=>e.nd+e.sd,pv=e=>e.prime+e.vr,rule='Seules les journées validées sont comptées dans « À payer » ; le reste apparaît en « En attente » jusqu’à validation.',plural=n=>n>1?'s':'',totLabel=`Total · ${rows.length===data.rows.length?`${rows.length} salarié${plural(rows.length)}`:`${rows.length} affiché${plural(rows.length)} sur ${data.rows.length}`}`;return `<div class="page-head recap-head"><div><span class="eyebrow kicker">GESTION / PAIE / TERRAIN</span><h1>Récap paie</h1><p>Synthèse mensuelle de la paie, salarié par salarié, tous dépôts confondus.</p></div></div>${recapTabsHtml()}<div class="rp"><div class="rp-bar"><div class="rp-f"><span>Mois</span>${paieMonthNav('rp-month',paieMonth)}</div><label class="rp-f">Dépôt<select id="rp-depot"><option value="">Tous les dépôts</option>${data.depots.map(d=>`<option value="${escapeAttr(d)}" ${recapMens.depot===d?'selected':''}>${esc(d)}</option>`).join('')}</select></label><label class="rp-f">État<select id="rp-state"><option value="">Tous</option><option value="incomplet" ${recapMens.state==='incomplet'?'selected':''}>Incomplets</option><option value="complet" ${recapMens.state==='complet'?'selected':''}>Complets</option><option value="vide" ${recapMens.state==='vide'?'selected':''}>Aucune saisie</option></select></label><label class="rp-f rp-grow">Recherche<input id="rp-search" placeholder="Rechercher un salarié…" value="${escapeAttr(recapMens.search)}"></label></div>${inc.length?`<div class="rp-banner">⚠ ${inc.length} salarié${plural(inc.length)} incomplet${plural(inc.length)} : ${[todoN?`${todoN} journée${plural(todoN)} non validée${plural(todoN)}`:'',missN?`${missN} tarif${plural(missN)} manquant${plural(missN)}`:'',draftN?`${draftN} brouillon${plural(draftN)}`:''].filter(Boolean).join(' · ')}. <b>${rule}</b></div>`:(rows.some(e=>e.active)?`<div class="rp-banner is-ok">✓ Tous les salariés affichés sont complets : journées validées, tarifs renseignés. ${rule}</div>`:'')}<div class="rp-chips">${hidden>0?`<span class="rp-chip">${hidden} salarié${plural(hidden)} sans saisie masqué${plural(hidden)} <button type="button" class="rp-linkbtn" id="rp-empty">Afficher</button></span>`:(recapMens.showEmpty&&emptyN&&!recapMens.state?'<span class="rp-chip">Salariés sans saisie affichés <button type="button" class="rp-linkbtn" id="rp-empty">Masquer</button></span>':'')}${recapMens.fold?'<button type="button" class="rp-chip rp-unfold" id="rp-unfold">‹ Afficher le panneau</button>':''}</div><div class="rp-layout${recapMens.open?' is-open':''}${recapMens.fold?' is-fold':''}"><div class="rp-list">${rows.length?`<table class="rp-t"><thead><tr><th>Salarié</th><th class="l">Dépôt</th><th>Jours</th><th>Récap</th><th title="Primes du récap et ${escapeAttr(paieVariablesLabel().toLowerCase())} validés">Prime / var.</th><th>À payer</th><th>En attente</th><th class="l">État</th></tr></thead><tbody>${rows.map(e=>`<tr data-rp-sel="${escapeAttr(e.s.id)}" tabindex="0" role="button" class="${sel&&sel.s.id===e.s.id?'sel':''}"><td>${recapEmployeeName(e.s)}${recapMensuelNoteBadge(e)}</td><td class="l">${recapMensuelDepots(e)}</td><td>${e.jours||'—'}</td><td>${z(rec(e))}</td><td>${sg(pv(e))}</td><td class="pay">${paieMoney(e.pay)}</td><td class="att">${e.wait>0?`+ ${paieMoney(e.wait)}`:'—'}</td><td class="l">${recapMensuelPill(e)}</td></tr>`).join('')}</tbody><tfoot><tr><td>${totLabel}</td><td></td><td>${tot('jours')}</td><td>${z(rows.reduce((a,e)=>a+rec(e),0))}</td><td>${sg(rows.reduce((a,e)=>a+pv(e),0))}</td><td class="pay">${paieMoney(tot('pay'))}</td><td class="att">${tot('wait')>0?`+ ${paieMoney(tot('wait'))}`:'—'}</td><td></td></tr></tfoot></table><div class="rp-cards">${rows.map(e=>`<div class="rp-card" data-rp-sel="${escapeAttr(e.s.id)}" tabindex="0" role="button"><div class="top"><b>${recapEmployeeName(e.s)}${recapMensuelNoteBadge(e)}</b><strong>${paieMoney(e.pay)}</strong></div><small>${recapMensuelDepots(e)} · ${e.jours} jour${plural(e.jours)}</small>${e.wait>0?`<small class="rp-wait">+ ${paieMoney(e.wait)} en attente de validation</small>`:''}<div class="bot"><span>${recapMensuelPill(e)}</span><small class="rp-lk">Voir le détail ›</small></div></div>`).join('')}<div class="rp-card rp-card-total"><div class="top"><b>${totLabel}</b><strong>${paieMoney(tot('pay'))}</strong></div>${tot('wait')>0?`<small class="rp-wait">+ ${paieMoney(tot('wait'))} en attente de validation</small>`:''}</div></div>`:'<div class="empty-state">Aucun salarié ne correspond.</div>'}</div>${recapMensuelFiche(sel)}</div></div>`}
function recapMensuelSelId(){const d=recapMensuelFiltered(recapMensuelData()),i=d.filter(e=>e.key==='incomplet');return (d.find(e=>e.s.id===recapMens.sel)||i[0]||d[0]||{s:{}}).s.id}
function bindRecapTabs(){document.querySelectorAll('[data-recap-tab]').forEach(b=>b.onclick=()=>{const k=b.dataset.recapTab;recapTab=k;if(k==='grille')recapView='mois';else if(k==='saisie'&&recapView==='mois')recapView='jour';render()})}
