const kpis=`<div class="pf-kpis">${pfPinned(m).map(l=>`<button type="button" class="pf-k${l.style==='final'?' is-final':''}" data-pf-jump="${l.id}" aria-label="Aller à ${escapeAttr(l.label)}"><span class="pf-kl">${esc(l.label)}</span><strong data-pf-kv="${l.id}">${pfEur(vals[l.id])}</strong><i aria-hidden="true">↓</i></button>`).join('')}</div>`;
