function drCardNd(cls,title,sub,lab,r){const due=n=>n>0?`<span class="dr-pl r">+${n}</span>`:'<span class="dr-z">0</span>';return `<div class="dr-rc ${cls}"><div class="dr-rh"><b>${title}</b><span>${sub}</span></div><table class="dr-mt"><thead><tr><th></th><th>Attendues</th><th>Chauffeurs</th><th>Payées</th><th>À réclamer</th></tr></thead><tbody><tr class="dr-gt dr-only"><th>${lab}</th><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${due(r[3])}</td></tr></tbody></table></div>`}
function drCardSd(cls,title,sub,rows){const cy=SAMEDAY_CYCLES,tot=[0,1,2,3].map(j=>rows.reduce((s,r)=>s+r[j],0)),due=n=>n>0?`<span class="dr-pl r">+${n}</span>`:'<span class="dr-z">0</span>';return `<div class="dr-rc ${cls}"><div class="dr-rh"><b>${title}</b><span>${sub}</span></div><table class="dr-mt"><thead><tr><th>Cycle</th><th>Attendues</th><th>Chauffeurs</th><th>Payées</th><th>À réclamer</th></tr></thead><tbody>${cy.map((k,i)=>`<tr><th>${k}</th><td>${rows[i][0]}</td><td>${rows[i][1]}</td><td>${rows[i][2]}</td><td>${due(rows[i][3])}</td></tr>`).join('')}<tr class="dr-gt"><th>Total général</th><td>${tot[0]}</td><td>${tot[1]}</td><td>${tot[2]}</td><td>${due(tot[3])}</td></tr></tbody></table></div>`}
function drRecapIntro(t){const svc=drSvc();return `<h2>Récap du mois${svc==='SAMEDAY'?' par cycle':''} : semaine, dimanches &amp; fériés, total</h2><p>${esc(svc)} · ${esc(drDepot())} · ${esc(paieMonthLabel(drS.month))} — uniquement les jours où le client a un chiffre saisi, pour que « attendues − payées = à réclamer » tombe juste. Un jour où le client paie plus que prévu ne compense pas un autre jour. Les chauffeurs comptent tous les jours dont le récap est saisi.${svc==='SAMEDAY'?' Chaque carte détaille les cycles A, E, B, C, D, avec un total général.':''}</p>`}
function drRecap(t){if(t.svc==='SAMEDAY')return drRecapSd(t);const jr=n=>`${n} jour${n>1?'s':''} comparé${n>1?'s':''}`,rt=(x,k)=>k==='r'?[x.a,x.c,x.p,x.rd,x.n]:[x.aa,x.ac,x.ap,x.ra,x.nA],row=k=>{const lab=k==='r'?'Routes':'ABT',a=rt(t.sem,k),b=rt(t.dim,k),c=rt(t.tot,k);return `<div class="dr-sect ${k}">${k==='r'?'NEXTDAY':'ABT'}</div><div class="dr-rg ${k==='a'?'abt':''}">${drCardNd('','Semaine',`lundi au samedi · ${jr(a[4])}`,lab,a)}${drCardNd('sun','Dimanches &amp; jours fériés',jr(b[4]),lab,b)}${drCardNd('tot','Total du mois',`semaine + dimanches &amp; fériés · ${jr(c[4])}`,lab,c)}</div>`};return drRecapIntro(t)+row('r')+row('a')}
function drRecapSd(t){const cy=SAMEDAY_CYCLES,jr=n=>`${n} jour${n>1?'s':''} comparé${n>1?'s':''}`,pick=(b,k)=>cy.map(c=>{const x=t.cy[c][b];return k==='r'?[x.a,x.c,x.p,x.rd,x.n]:[x.aa,x.ac,x.ap,x.ra,x.nA]}),mx=rows=>Math.max(0,...rows.map(r=>r[4])),row=k=>{const s=pick('sem',k),d=pick('dim',k),o=pick('tot',k);return `<div class="dr-sect ${k==='r'?'r sd':'a'}">${k==='r'?'SAMEDAY':'ABT'}</div><div class="dr-rg dr-sdg ${k==='a'?'abt':''}">${drCardSd('','Semaine',`lundi au samedi · ${jr(mx(s))}`,s)}${drCardSd('sun','Dimanches &amp; jours fériés',jr(mx(d)),d)}${drCardSd('tot','Total du mois',`semaine + dimanches &amp; fériés · ${jr(mx(o))}`,o)}</div>`};return drRecapIntro(t)+row('r')+row('a')}
function drNdHead(svc){return `<tr class="g"><th class="l"></th><th colspan="4" class="r"><span>${svc}</span></th><th colspan="4" class="a dr-sep"><span>ABT</span></th></tr><tr><th class="l">Jour</th><th>Nb routes<br>attendues</th><th>Nb chauffeurs<br>payés</th><th>Nb routes<br>payées</th><th>Différence</th><th class="dr-sep">Nb ABT<br>attendues</th><th>Nb chauffeurs<br>ABT</th><th>Nb ABT<br>payées</th><th>Différence</th></tr>`}
function drSdHead(){const cy=SAMEDAY_CYCLES,names=['Nb SAMEDAY<br>attendues','Nb chauffeurs<br>payés','Nb SAMEDAY<br>payés','Différence','Nb ABT<br>attendues','Nb chauffeurs<br>ABT','Nb ABT<br>payées','Différence'];return `<tr class="g"><th class="l"></th><th colspan="20" class="sd"><span>SAMEDAY</span></th><th colspan="20" class="a dr-sep"><span>ABT</span></th></tr><tr><th class="l"></th>${names.map((n,i)=>`<th colspan="5" class="grp${drSepCls(i,0)}">${n}</th>`).join('')}</tr><tr><th class="l">Jour</th>${names.map((n,i)=>cy.map((k,j)=>`<th class="cy${drSepCls(i,j)}">${k}</th>`).join('')).join('')}</tr>`}
function directionRoutesPage(){const depots=drDepots(),depot=drDepot(),svc=drSvc(),sd=servicesForDepot(depot).includes('SAMEDAY'),nd=servicesForDepot(depot).includes('NEXTDAY'),t=drTotals(),isSd=svc==='SAMEDAY';if(!depots.length)return '<div class="empty-state">Aucun dépôt.</div>';return `<div class="page-head"><div><span class="eyebrow kicker">DIRECTION / ROUTES</span><h1>Récap Routes</h1><p>Ce que le client devait vous payer, comparé à ce qu’il vous a payé, jour par jour.</p></div><div class="head-actions">${paieMonthNav('dr-month',drS.month)}<button type="button" class="btn light small" id="dr-csv"><i data-lucide="download" aria-hidden="true"></i> Export CSV</button><button type="button" class="btn primary small" id="dr-copy"><i data-lucide="copy" aria-hidden="true"></i> Copier pour la réclamation</button></div></div><div class="dr-bar"><select id="dr-depot" class="vr-sel" aria-label="Dépôt">${depots.map(d=>`<option value="${escapeAttr(d)}"${d===depot?' selected':''}>${esc(d)}</option>`).join('')}</select><span class="dr-seg" role="group" aria-label="Service">${nd?`<button type="button" class="${svc==='NEXTDAY'?'on':''}" data-dr-svc="NEXTDAY" aria-pressed="${svc==='NEXTDAY'}">NEXTDAY</button>`:''}${sd?`<button type="button" class="${isSd?'on':''}" data-dr-svc="SAMEDAY" aria-pressed="${isSd}">SAMEDAY</button>`:''}</span></div><div class="dr-wrap"><table class="dr-table ${isSd?'dr3':'nd'}"><thead>${isSd?drSdHead():drNdHead(svc)}</thead><tbody id="dr-body">${t.rows.map(isSd?drRowHtmlSd:drRowHtml).join('')}${isSd?drTotRowSd(t):drTotRow(t)}</tbody></table></div><div class="dr-legend"><span><i></i>jour à vérifier (il y a quelque chose à réclamer)</span><span><em></em>dimanche ou jour férié</span><span>attendues, payées, à réclamer : jours comparés · chauffeurs : tous les jours saisis</span></div><section class="dr-rec" id="dr-rec">${drRecap(t)}</section><p class="dr-note"><b>Différence</b> = attendues − payées par le client (rouge : le client doit des routes ; gris : il en a payé plus). Attendues et ABT attendues viennent du FC du jour ; chauffeurs payés et chauffeurs ABT du récap du jour ; seules les cases « payées » se saisissent ici, d’après le tableau du client. Le nombre de chauffeurs est une information : la réclamation se base sur les routes attendues. Aucun montant en euros.</p>`}
