function drReclaimText(){const t=drTotals(),depot=drDepot(),svc=drSvc(),head=`Réclamation routes — ${depot} · ${svc} · ${paieMonthLabel(drS.month)}`,lines=[],lab=d=>new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});let tr=0,ta=0;if(svc==='NEXTDAY'){t.rows.forEach(c=>{if(!(c.rd>0||c.ad>0))return;const parts=[];if(c.rd>0)parts.push(`${c.rB.a} routes attendues, ${c.rB.b} payées : ${c.rd} route${c.rd>1?'s':''} à réclamer`);if(c.ad>0)parts.push(`${c.aB.a} ABT attendues, ${c.aB.b} payées : ${c.ad} ABT à réclamer`);lines.push(`- ${lab(c.date)} : ${parts.join(' ; ')}`)});tr=t.tot.rd;ta=t.tot.ra}else{t.rows.forEach(r=>{const parts=[];SAMEDAY_CYCLES.forEach(k=>{const c=r.cs[k];if(c.rd>0)parts.push(`cycle ${k} : ${c.rB.a} attendues, ${c.rB.b} payées : ${c.rd} à réclamer`);if(c.ad>0)parts.push(`cycle ${k} ABT : ${c.aB.a} attendues, ${c.aB.b} payées : ${c.ad} à réclamer`)});if(parts.length)lines.push(`- ${lab(r.date)} : ${parts.join(' ; ')}`)});SAMEDAY_CYCLES.forEach(k=>{tr+=t.cy[k].tot.rd;ta+=t.cy[k].tot.ra})}if(!lines.length)return head+'\nRien à réclamer sur les jours renseignés.';return head+'\n'+lines.join('\n')+`\nTotal : ${tr} route${tr>1?'s':''} · ${ta} ABT.`}
