const byPlate={};alerts.forEach(a=>{(byPlate[a.plate]=byPlate[a.plate]||[]).push(a)});const SH={'Contrôle technique':'CT','Vidange':'VIDANGE','Km non relevé':'KM','Assurance':'ASSURANCE','Carte grise':'CG'};
