function vehicleSortValue(v,key){switch(key){case'plate':return String(v.plate||'');case'vehicle':return `${v.brand||''} ${v.model||''}`.trim();case'activity':return `${v.activity||''} ${v.company||''}`.trim();case'depot':return v.depot||'';case'condition':return String(v.condition||'').toUpperCase()==='HS'?0:1;case'km':return v.km==null||v.km===''?null:Number(v.km);case'oil':{let n=nextOil(v);return n==null?null:Number(n)-Number(v.km||0)}case'ct':{let d=ctDateFor(v);if(!d)return null;let t=Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(String(d))?`${d}T00:00:00`:d);return Number.isFinite(t)?t:null}default:return ''}}
function compareVehicleSort(a,b,key,direction){let av=vehicleSortValue(a,key),bv=vehicleSortValue(b,key),an=av==null||av===''||Number.isNaN(av),bn=bv==null||bv===''||Number.isNaN(bv);if(an||bn)return an===bn?0:(an?1:-1);let cmp=key==='plate'||key==='vehicle'||key==='activity'||key==='depot'?String(av).localeCompare(String(bv),'fr',{numeric:true,sensitivity:'base'}):key==='condition'?Number(av)-Number(bv):Number(av)-Number(bv);return cmp*direction}
function sortedVehicles(list){if(!vehicleSort.key||!vehicleSort.direction)return list;let order=new Map(list.map((v,i)=>[v,i]));return [...list].sort((a,b)=>compareVehicleSort(a,b,vehicleSort.key,vehicleSort.direction)||order.get(a)-order.get(b))}
function cycleVehicleSort(key){if(vehicleSort.key!==key)vehicleSort={key,direction:1};else if(vehicleSort.direction===1)vehicleSort.direction=-1;else vehicleSort={key:null,direction:0};render()}
function bindVehicleSortHeaders(){document.querySelectorAll('[data-vehicle-sort]').forEach(th=>{th.onclick=e=>{e.stopPropagation();cycleVehicleSort(th.dataset.vehicleSort)};th.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();cycleVehicleSort(th.dataset.vehicleSort)}}})}
function sortHeader(label,key){let active=vehicleSort.key===key,arrow=active?(vehicleSort.direction===1?' ▲':' ▼'):'';return `<th class=\"sortable-th${active?' is-sorted':''}\" data-vehicle-sort=\"${key}\" tabindex=\"0\" role=\"button\" aria-sort=\"${active?(vehicleSort.direction===1?'ascending':'descending'):'none'}\" title=\"Trier par ${label.toLocaleLowerCase('fr')}\">${label}<span class=\"sort-arrow\" aria-hidden=\"true\">${arrow}</span></th>`}
