/* SAMEDAY - début */
const SAMEDAY_CYCLES=['A','E','B','C','D'];
function samedayOpenCycles(depot){return servicesForDepot(depot).includes('SAMEDAY')?[...SAMEDAY_CYCLES]:[]}
function samedayCanManageSalary(userRole){return ['administrateur','responsable','rh'].includes(userRole)}
function samedayAddSalaryRate(salary,userRole,record){
 if(!samedayCanManageSalary(userRole)||!salary||!record||!SAMEDAY_CYCLES.includes(record.cycle)||!/^\d{4}-\d{2}-\d{2}$/.test(record.effectiveDate||''))return false;
 const weekly=Number(record.weeklyRate),sunday=Number(record.sundayRate);
 if(!Number.isFinite(weekly)||weekly<0||!Number.isFinite(sunday)||sunday<0)return false;
 if(!Array.isArray(salary.samedayRateHistory))salary.samedayRateHistory=[];
 const entry={cycle:record.cycle,effectiveDate:record.effectiveDate,weeklyRate:weekly,sundayRate:sunday,createdAt:record.createdAt||new Date().toISOString()};
 const index=salary.samedayRateHistory.findIndex(x=>x.cycle===entry.cycle&&x.effectiveDate===entry.effectiveDate);
 if(index<0)salary.samedayRateHistory.push(entry);else salary.samedayRateHistory[index]=entry;
 salary.samedayRateHistory.sort((a,b)=>(a.effectiveDate||'').localeCompare(b.effectiveDate||'')||SAMEDAY_CYCLES.indexOf(a.cycle)-SAMEDAY_CYCLES.indexOf(b.cycle));
 return true;
}
function samedayRateAt(salary,cycle,date=currentDate()){
 const history=Array.isArray(salary?.samedayRateHistory)?salary.samedayRateHistory:[];
 return history.filter(r=>r&&r.cycle===cycle&&typeof r.effectiveDate==='string'&&r.effectiveDate<=date).sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate))[0]||null;
}
const _samedayBasePaieEmployeePage=paieEmployeePage;
function samedayPaieEmployeePage(){
 let html=_samedayBasePaieEmployeePage();if(!canManageSalary())return html;
 const salary=paieSalaries().find(y=>y.id===selectedSalarie);if(!salary)return html;
 const history=Array.isArray(salary.samedayRateHistory)?salary.samedayRateHistory.filter(r=>r&&typeof r==='object'&&/^\d{4}-\d{2}-\d{2}$/.test(r.effectiveDate||'')):[];
 const dates=[...new Set(history.map(r=>r.effectiveDate))].sort((a,b)=>b.localeCompare(a));
 const latest=dates.slice(0,3), extra=dates.slice(3);
 const cell=(date,cycle)=>{const r=history.find(x=>x.effectiveDate===date&&x.cycle===cycle);return r?`<span class="sameday-rate-cell"><small>Salaire semaine</small> ${paieMoney(r.weeklyRate)}<br><small>Salaire dimanche et jours fériés</small> ${paieMoney(r.sundayRate)}</span>`:'<span class="sameday-rate-cell">—</span>'};
 const row=date=>`<tr data-sameday-date-row="${escapeAttr(date)}" class="${extra.includes(date)?'hidden':''}"><td>${fmtDate(date)}</td>${SAMEDAY_CYCLES.map(c=>`<td>${cell(date,c)}</td>`).join('')}</tr>`;
 const section=`<section class="detail-section sameday-salary-rates"><div class="docs-heading"><div><h3>Rémunération SameDay</h3></div></div><div class="table-wrap" style="overflow-x:auto;max-width:100%"><table class="fleet-table paie-table" style="min-width:650px;table-layout:fixed"><thead><tr><th>DATE D’EFFET</th>${SAMEDAY_CYCLES.map(c=>`<th>CYCLE ${c}</th>`).join('')}</tr></thead><tbody>${latest.map(row).join('')}${extra.map(row).join('')||(!dates.length?'<tr><td colspan="6" class="empty-state">Aucun tarif SameDay enregistré.</td></tr>':'')}</tbody></table></div>${extra.length?`<button class="link-button" type="button" data-sameday-history-toggle aria-expanded="false">Voir tout l’historique (${dates.length})</button>`:''}</section>`;
 return html.replace('<section class="detail-section docs-section salary-docs">',section+'<section class="detail-section docs-section salary-docs">');
}
