 const form=$('#paie-salary-form');if(!form||!canManageSalary())return;
 const initial=SAMEDAY_CYCLES.map(c=>{const r=samedayRateAt(sal||null,c);return {cycle:c,weeklyRate:r?.weeklyRate??'',sundayRate:r?.sundayRate??''}});
 const effectiveDates=initial.map(r=>samedayRateAt(sal||null,r.cycle)?.effectiveDate||'').filter(Boolean).sort();const latestSamedayDate=effectiveDates[effectiveDates.length-1]||'';
 const section=document.createElement('section');section.className='salary-form-section sameday-edit-rates';section.setAttribute('aria-labelledby','salary-sameday-title');
 section.innerHTML=`<h3 id="salary-sameday-title" class="salary-section-title"><i data-lucide="wallet-cards" aria-hidden="true"></i> Rémunération SameDay</h3><p class="salary-field-help">Un tarif par groupe de cycles. Un cycle sans tarif conserve son historique.</p><div class="sameday-edit-effective"><label>Date d’effet du tarif<input name="samedayEffectiveDate" type="date" value="${escapeAttr(latestSamedayDate)}"></label></div><div id="sd-blocks" class="sd-blocks"></div><button type="button" class="link-button sd-add-block" id="sd-add-block">+ Ajouter un autre tarif</button><div class="sameday-cycle-grid" hidden>${initial.map(r=>`<div class="salary-form-grid salary-pay-grid sameday-cycle-rate"><label>Cycle ${r.cycle}</label><label>Salaire semaine (€)<input type="number" min="0" step="0.01" data-sameday-weekly="${r.cycle}" value="${escapeAttr(r.weeklyRate)}"></label><label>Salaire dimanche et jours fériés (€)<input type="number" min="0" step="0.01" data-sameday-sunday="${r.cycle}" value="${escapeAttr(r.sundayRate)}"></label></div>`).join('')}</div>`;
 const notes=form.querySelector('[aria-labelledby="salary-notes-title"]');if(notes)form.insertBefore(section,notes);else form.appendChild(section);
 const sdBox=section.querySelector('#sd-blocks'),sdCyc=SAMEDAY_CYCLES;
 const sdBlockHtml=(cycles,w,u)=>`<div class="sd-block"><div class="sd-block-head"><span>Cycles concernés</span><button type="button" class="link-button" data-sd-remove>Retirer</button></div><div class="gp-sd-cycles">${sdCyc.map(c=>`<label class="recap-cycle-check"><input type="checkbox" data-sd-chip="${c}" ${cycles.includes(c)?'checked':''}><span>${c}</span></label>`).join('')}</div><div class="sd-block-fields"><label>Salaire semaine (€)<input type="number" min="0" step="0.01" inputmode="decimal" placeholder="0,00" data-sd-w value="${escapeAttr(w)}"></label><label>Dimanche et jours fériés (€)<input type="number" min="0" step="0.01" inputmode="decimal" placeholder="0,00" data-sd-u value="${escapeAttr(u)}"></label></div></div>`;
 const sdSync=()=>{const val={};sdBox.querySelectorAll('.sd-block').forEach(b=>{const w=b.querySelector('[data-sd-w]').value,u=b.querySelector('[data-sd-u]').value;b.querySelectorAll('[data-sd-chip]:checked').forEach(i=>{val[i.dataset.sdChip]={w,u}})});sdCyc.forEach(c=>{const wi=section.querySelector(`[data-sameday-weekly="${c}"]`),ui=section.querySelector(`[data-sameday-sunday="${c}"]`);wi.value=val[c]?val[c].w:'';ui.value=val[c]?val[c].u:''})};
